["16:18"]={{q="十六时鸣犬急，十八分昙花落。",t="分钟之诗",a="Antonoko / GPT-4",m="16:18"},{q="时值午后十六，分指如流十八。",t="分钟之诗",a="Antonoko / GPT-4",m="16:18"},{q="十六点钟声振，十八分摇晚风。",t="分钟之诗",a="Antonoko / GPT-4",m="16:18"},{q="日暮时分十六，十八瞬息即过。",t="分钟之诗",a="Antonoko / GPT-4",m="16:18"},{q="钟点指向十六，分钟滴嗒至十八。",t="分钟之诗",a="Antonoko / GPT-4",m="16:18"}},
["16:19"]={{q="十六点钟鸣，篇章久已情。",t="分钟之诗",a="Antonoko / GPT-4",m="16:19"},{q="温酒煮掌中，晚夜十六分。",t="分钟之诗",a="Antonoko / GPT-4",m="16:19"},{q="江河已漓漉，十六映月辉。",t="分钟之诗",a="Antonoko / GPT-4",m="16:19"},{q="慵懒才子寺，笔下是十六。",t="分钟之诗",a="Antonoko / GPT-4",m="16:19"},{q="故人对门立，一酌至十六。",t="分钟之诗",a="Antonoko / GPT-4",m="16:19"}},
["16:20"]={{q="十六点时分春意阑，芳菲事过二十寒。",t="分钟之诗",a="Antonoko / GPT-4",m="16:20"},{q="时逾四点二十刻，阳光斜照映窗幕。",t="分钟之诗",a="Antonoko / GPT-4",m="16:20"},{q="午后时光步不疾，十六点二十犹如翠。",t="分钟之诗",a="Antonoko / GPT-4",m="16:20"},{q="夕阳偏挂十六时，花影点点二十分。",t="分钟之诗",a="Antonoko / GPT-4",m="16:20"},{q="钟鼓报时已十六，天光犹在二十里。",t="分钟之诗",a="Antonoko / GPT-4",m="16:20"}},
["16:21"]={{q="十六时已过春分夜，二一分半柳絮飞。",t="分钟之诗",a="Antonoko / GPT-4",m="16:21"},{q="十六时辰水波里，二一点点樱花细。",t="分钟之诗",a="Antonoko / GPT-4",m="16:21"},{q="硕果满枝待十六，二一微风解香含。",t="分钟之诗",a="Antonoko / GPT-4",m="16:21"},{q="十六辰时莺歌破，二一春分金鱼悠。",t="分钟之诗",a="Antonoko / GPT-4",m="16:21"},{q="积雪融于十六日，清泉跃下二一石。",t="分钟之诗",a="Antonoko / GPT-4",m="16:21"}},
