["17:21"]={{q="十七时钟挂墙偏，春色满园时间转。",t="分钟之诗",a="Antonoko / GPT-4",m="17:21"},{q="二十一分残阳下，春风独坐意悠长。",t="分钟之诗",a="Antonoko / GPT-4",m="17:21"},{q="簪花十七春光新，二一点时芳草醇。",t="分钟之诗",a="Antonoko / GPT-4",m="17:21"},{q="时至傍晚十七钟，二一分鸣春意浓。",t="分钟之诗",a="Antonoko / GPT-4",m="17:21"},{q="十七时辰春念生，黄昏二十一分轻。",t="分钟之诗",a="Antonoko / GPT-4",m="17:21"}},
["17:22"]={{q="五月花繁盛，零七二二鸣蝉。",t="分钟之诗",a="Antonoko / GPT-4",m="17:22"},{q="雨后江边立，十七二十二春光新。",t="分钟之诗",a="Antonoko / GPT-4",m="17:22"},{q="秋水共长天，时至十七二二秋月明。",t="分钟之诗",a="Antonoko / GPT-4",m="17:22"},{q="春风十七里，二十二分燕归巢。",t="分钟之诗",a="Antonoko / GPT-4",m="17:22"},{q="绿水青山间，日暮十七二二春雪晚。",t="分钟之诗",a="Antonoko / GPT-4",m="17:22"}},
["17:23"]={{q="十七点已快过，二三分转眼飞。",t="分钟之诗",a="Antonoko / GPT-4",m="17:23"},{q="晚风起，十七时，长啸随二三分。",t="分钟之诗",a="Antonoko / GPT-4",m="17:23"},{q="时分十七望天边，二三刻露已生烟。",t="分钟之诗",a="Antonoko / GPT-4",m="17:23"},{q="时刻如流，十七度落夜幕，二三字裁秋水。",t="分钟之诗",a="Antonoko / GPT-4",m="17:23"},{q="十且七，致夏日已尾，分转二与三，月光初上。",t="分钟之诗",a="Antonoko / GPT-4",m="17:23"}},
["17:24"]={{q="『晚霞映衣红十七，鸣蝉出壳应廿四。』",t="分钟之诗",a="Antonoko / GPT-4",m="17:24"},{q="『十七时辰破夜静，廿四瞬间化春霜。』",t="分钟之诗",a="Antonoko / GPT-4",m="17:24"},{q="『半夜半魄度十七，廿四举杯酹长江。』",t="分钟之诗",a="Antonoko / GPT-4",m="17:24"},{q="『宛如十七辞旧梦，廿四韵尾涤蒹葭。』",t="分钟之诗",a="Antonoko / GPT-4",m="17:24"},{q="『 十七鸣钟映月明，廿四落花霜满径。』",t="分钟之诗",a="Antonoko / GPT-4",m="17:24"}},
["17:25"]={{q="十七点钟声伴晚照，二十五分春色调。",t="分钟之诗",a="Antonoko / GPT-4",m="17:25"},{q="五点三刻诗思到，春日草长莺自娆。",t="分钟之诗",a="Antonoko / GPT-4",m="17:25"},{q="时至十七莫相催，点滴春色半还回。",t="分钟之诗",a="Antonoko / GPT-4",m="17:25"},{q="橙蕊染晚三分二，蒹葭释怀春色醉。",t="分钟之诗",a="Antonoko / GPT-4",m="17:25"},{q="春日十七点，二十五分花开催。",t="分钟之诗",a="Antonoko / GPT-4",m="17:25"}},
["17:26"]={{q="春风轻舞十七时，柳絮纷飞二十六分。",t="分钟之诗",a="Antonoko / GPT-4",m="17:26"},{q="晚风轻轻十七破，唤醒了二十六的闲梦。",t="分钟之诗",a="Antonoko / GPT-4",m="17:26"},{q="星辰熠熠，十七时辉，月上柳梢头，二十六分秋。",t="分钟之诗",a="Antonoko / GPT-4",m="17:26"},{q="明月十七时照影，沧海澄清二十六分界。",t="分钟之诗",a="Antonoko / GPT-4",m="17:26"},{q="十七之时归雁南，二十六分霜满田。",t="分钟之诗",a="Antonoko / GPT-4",m="17:26"}},
["17:27"]={{q="十七点，晚霞应照窗，诗书知已禅。",t="分钟之诗",a="Antonoko / GPT-4",m="17:27"},{q="时至昏鸦岁，二十七钟声漠漠入鹿门。",t="分钟之诗",a="Antonoko / GPT-4",m="17:27"},{q="赏黄昏华灯七点，清风伴我吟红尘。",t="分钟之诗",a="Antonoko / GPT-4",m="17:27"},{q="独步薄暮下，看尽世间繁华情，华灯初上十七刻。",t="分钟之诗",a="Antonoko / GPT-4",m="17:27"},{q="春风吹遍花开处，点点灯火藏春温，十七更鼓振蓬瀛。",t="分钟之诗",a="Antonoko / GPT-4",m="17:27"}},
["17:28"]={{q="\"夕阳西下逢十七，时光犹在涌黄昏。\"",t="分钟之诗",a="Antonoko / GPT-4",m="17:28"},{q="\"诗韵轻摇在十七，墨香四溢色黄昏。\"",t="分钟之诗",a="Antonoko / GPT-4",m="17:28"},{q="\"十七点二十有八，黄昏洒落画卷中。\"",t="分钟之诗",a="Antonoko / GPT-4",m="17:28"},{q="\"黄昏十七闪金辉，索尽长天一点钟。\"",t="分钟之诗",a="Antonoko / GPT-4",m="17:28"},{q="\"诗笔飞扬至十七，晚霞洒满石板路。\"",t="分钟之诗",a="Antonoko / GPT-4",m="17:28"}},
["17:29"]={{q="十七时穿云漏，晚霞映水湖光绿。",t="分钟之诗",a="Antonoko / GPT-4",m="17:29"},{q="二九分割蓝天，夕阳黄昏独果然。",t="分钟之诗",a="Antonoko / GPT-4",m="17:29"},{q="钟到十七无声响，晚风如诗且慢慢。",t="分钟之诗",a="Antonoko / GPT-4",m="17:29"},{q="牛骨钟声余十七，花开晚景坐江船。",t="分钟之诗",a="Antonoko / GPT-4",m="17:29"},{q="秋水共长天一色，十七分时景更说。",t="分钟之诗",a="Antonoko / GPT-4",m="17:29"}},
["17:30"]={{q="十七点半，山川锁晚霞。",t="分钟之诗",a="Antonoko / GPT-4",m="17:30"},{q="春江半过午后期，十七半点独自思。",t="分钟之诗",a="Antonoko / GPT-4",m="17:30"},{q="日照半边山，十七点三积思量。",t="分钟之诗",a="Antonoko / GPT-4",m="17:30"},{q="欲知别样春，十七半点时已长。",t="分钟之诗",a="Antonoko / GPT-4",m="17:30"},{q="暮色江头夕阳斜，十七半点沉思在桥下。",t="分钟之诗",a="Antonoko / GPT-4",m="17:30"}},
